    "appreciation": "《蜀道难》是李白的名篇。全诗从具体景物和真切情感出发，语言凝练，意境悠远，适合结合课本诵读与赏析。",
    "lines": [
      {
        "text": "噫吁戏！危乎高哉！蜀道之难难于上青天！蚕丛及鱼凫，开国何茫然。",
        "pinyin": "yī xū xì wēi hū gāo zāi shǔ dào zhī nán nán yú shàng qīng tiān cán cóng jí yú fú kāi guó hé máng rán",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "尔来四万八千岁，不与秦塞通人烟。",
        "pinyin": "ěr lái sì wàn bā qiān suì bù yǔ qín sāi tōng rén yān",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "西当太白有鸟道，可以横绝峨眉巅。",
        "pinyin": "xī dāng tài bái yǒu niǎo dào kě yǐ héng jué é méi diān",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "地崩山摧壮士死，然后天梯石栈相钩连。",
        "pinyin": "dì bēng shān cuī zhuàng shì sǐ rán hòu tiān tī shí zhàn xiāng gōu lián",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "上有六龙回日之高标，下有冲波逆折之回川。",
        "pinyin": "shàng yǒu liù lóng huí rì zhī gāo biāo xià yǒu chōng bō nì zhé zhī huí chuān",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "黄鹤之飞尚不得过，猨猱欲度愁攀援。",
        "pinyin": "huáng hè zhī fēi shàng bù dé guò yuán náo yù dù chóu pān yuán",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "青泥何盘盘，百步九折萦岩峦。",
        "pinyin": "qīng ní hé pán pán bǎi bù jiǔ zhé yíng yán luán",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "扪参历井仰胁息，以手抚膺坐长叹。",
        "pinyin": "mén cān lì jǐng yǎng xié xī yǐ shǒu fǔ yīng zuò zhǎng tàn",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "问君西游何时还？畏途巉岩不可攀。",
        "pinyin": "wèn jūn xī yóu hé shí hái wèi tú chán yán bù kě pān",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "但见悲鸟号古木，雄飞雌从绕林间。",
        "pinyin": "dàn jiàn bēi niǎo hào gǔ mù xióng fēi cí cóng rào lín jiān",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "又闻子规啼夜月，愁空山，蜀道之难难于上青天，使人听此凋朱颜。",
        "pinyin": "yòu wén zi guī tí yè yuè chóu kōng shān shǔ dào zhī nán nán yú shàng qīng tiān shǐ rén tīng cǐ diāo zhū yán",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "连峰去天不盈尺，枯松倒挂倚绝壁。",
        "pinyin": "lián fēng qù tiān bù yíng chǐ kū sōng dào guà yǐ jué bì",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "飞湍瀑流争喧豗，砅厓转石万壑雷。",
        "pinyin": "fēi tuān pù liú zhēng xuān huī lì yá zhuǎn shí wàn hè léi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "其险也如此，嗟尔远道之人胡为乎来哉！劒阁峥嵘而崔嵬，一夫当关，万夫莫开。",
        "pinyin": "qí xiǎn yě rú cǐ jiē ěr yuǎn dào zhī rén hú wèi hū lái zāi jiàn gé zhēng róng ér cuī wéi yī fū dāng guān wàn fū mò kāi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "所守或匪亲，化为狼与豺。",
        "pinyin": "suǒ shǒu huò fěi qīn huà wèi láng yǔ chái",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "朝避猛虎，夕避长蛇。",
        "pinyin": "cháo bì měng hǔ xī bì zhǎng shé",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "磨牙吮血，杀人如麻。",
        "pinyin": "mó yá shǔn xuè shā rén rú má",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "锦城虽云乐，不如早还家。",
        "pinyin": "jǐn chéng suī yún lè bù rú zǎo hái jiā",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "蜀道之难难于上青天，侧身西望长咨嗟。",
        "pinyin": "shǔ dào zhī nán nán yú shàng qīng tiān cè shēn xī wàng zhǎng zī jiē",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
