    "appreciation": "《相和歌辞 燕歌行》是高适的名篇。全诗从具体景物和真切情感出发，语言凝练，意境悠远，适合结合课本诵读与赏析。",
    "lines": [
      {
        "text": "汉家烟尘在东北，汉将辞家破残贼。",
        "pinyin": "hàn jiā yān chén zài dōng běi hàn jiāng cí jiā pò cán zéi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "男儿本自重横行，天子非常赐颜色。",
        "pinyin": "nán ér běn zì zhòng héng xíng tiān zi fēi cháng cì yán sè",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "𪭢金伐鼓下榆关，旌旗逶迤碣石间。",
        "pinyin": "chuāng jīn fá gǔ xià yú guān jīng qí wēi yí jié shí jiān",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "校尉羽书飞瀚海，单于猎火照狼山。",
        "pinyin": "xiào wèi yǔ shū fēi hàn hǎi dān yú liè huǒ zhào láng shān",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "山川萧条极边土，胡骑凭凌杂风雨。",
        "pinyin": "shān chuān xiāo tiáo jí biān tǔ hú qí píng líng zá fēng yǔ",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "战士军前半死生，美人帐下犹歌舞。",
        "pinyin": "zhàn shì jūn qián bàn sǐ shēng měi rén zhàng xià yóu gē wǔ",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "大漠穷秋塞草衰，孤城落日鬬兵稀。",
        "pinyin": "dà mò qióng qiū sāi cǎo shuāi gū chéng luò rì dòu bīng xī",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "身当恩遇常轻敌，力尽关山未解围。",
        "pinyin": "shēn dāng ēn yù cháng qīng dí lì jǐn guān shān wèi jiě wéi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "铁衣远戍辛勤久，玉箸应啼别离后。",
        "pinyin": "tiě yī yuǎn shù xīn qín jiǔ yù zhù yīng tí bié lí hòu",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "少妇城南欲断肠，征人蓟北空回首。",
        "pinyin": "shǎo fù chéng nán yù duàn cháng zhēng rén jì běi kōng huí shǒu",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "边风飘飘那可度，绝域苍茫更何有。",
        "pinyin": "biān fēng piāo piāo nà kě dù jué yù cāng máng gèng hé yǒu",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "杀气三日作阵云，寒声一夜传刁斗。",
        "pinyin": "shā qì sān rì zuò zhèn yún hán shēng yī yè chuán diāo dòu",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "相看白刃血纷纷，死节从来岂顾勋。",
        "pinyin": "xiāng kàn bái rèn xuè fēn fēn sǐ jié cóng lái qǐ gù xūn",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "君不见沙场征战苦，至今犹忆李将军。",
        "pinyin": "jūn bù jiàn shā chǎng zhēng zhàn kǔ zhì jīn yóu yì lǐ jiāng jūn",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
