    "appreciation": "《山石》是韩愈的名篇。全诗从具体景物和真切情感出发，语言凝练，意境悠远，适合结合课本诵读与赏析。",
    "lines": [
      {
        "text": "山石荦确行径微，黄昏到寺蝙蝠飞。",
        "pinyin": "shān shí luò què xíng jìng wēi huáng hūn dào sì biān fú fēi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "升堂坐阶新雨足，芭蕉叶大支子肥。",
        "pinyin": "shēng táng zuò jiē xīn yǔ zú bā jiāo yè dà zhī zi féi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "僧言古壁佛画好，以火来照所见稀。",
        "pinyin": "sēng yán gǔ bì fú huà hǎo yǐ huǒ lái zhào suǒ jiàn xī",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "铺床拂席置羹饭，疎粝亦足饱我饥。",
        "pinyin": "pù chuáng fú xí zhì gēng fàn shū lì yì zú bǎo wǒ jī",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "夜深静卧百虫绝，清月出岭光入扉。",
        "pinyin": "yè shēn jìng wò bǎi chóng jué qīng yuè chū lǐng guāng rù fēi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "天明独去无道路，出入高下穷烟霏。",
        "pinyin": "tiān míng dú qù wú dào lù chū rù gāo xià qióng yān fēi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "山红涧碧纷烂漫，时见松枥皆十围。",
        "pinyin": "shān hóng jiàn bì fēn làn màn shí jiàn sōng lì jiē shí wéi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "当流赤足蹋涧石，水声激激风吹衣。",
        "pinyin": "dāng liú chì zú tà jiàn shí shuǐ shēng jī jī fēng chuī yī",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "人生如此自可乐，岂必局束为人鞿。",
        "pinyin": "rén shēng rú cǐ zì kě lè qǐ bì jú shù wèi rén jī",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "嗟哉吾党二三子，安得至老不更归。",
        "pinyin": "jiē zāi wú dǎng èr sān zi ān dé zhì lǎo bù gèng guī",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
