    "lines": [
      {
        "text": "四月南风大麦黄，枣花未落桐阴长。",
        "pinyin": "sì yuè nán fēng dà mài huáng zǎo huā wèi luò tóng yīn zhǎng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "青山朝别暮还见，嘶马出门思旧乡。",
        "pinyin": "qīng shān cháo bié mù hái jiàn sī mǎ chū mén sī jiù xiāng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "陈侯立身何坦荡，虬须虎眉仍大颡。",
        "pinyin": "chén hóu lì shēn hé tǎn dàng qiú xū hǔ méi réng dà sǎng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "腹中贮书一万卷，不肯低头在草莽。",
        "pinyin": "fù zhōng zhù shū yī wàn juǎn bù kěn dī tóu zài cǎo mǎng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "东门酤酒饮我曹，心轻万事皆鸿毛。",
        "pinyin": "dōng mén gū jiǔ yǐn wǒ cáo xīn qīng wàn shì jiē hóng máo",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "醉卧不知白日暮，有时空望孤云高。",
        "pinyin": "zuì wò bù zhī bái rì mù yǒu shí kōng wàng gū yún gāo",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "长河浪头连天黑，津口停舟渡不得。",
        "pinyin": "zhǎng hé làng tóu lián tiān hēi jīn kǒu tíng zhōu dù bù dé",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "郑国游人未及家，洛阳行子空叹息。",
        "pinyin": "zhèng guó yóu rén wèi jí jiā luò yáng xíng zi kōng tàn xī",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "闻道故林相识多，罢官昨日今如何。",
        "pinyin": "wén dào gù lín xiāng shí duō bà guān zuó rì jīn rú hé",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
    "image": "https://readforfun-img.chunyangwen.com/tang-shi/images/li-qi---song-chen-zhang-fu/poem.webp"
